from solution import solve


assert solve({}, {}, {}) == []
assert solve({"a":[]}, {"X":["a"]}, {"X":1}) == []
assert solve({"a":["X"]}, {"X":[]}, {"X":1}) == []
assert solve({"a":["X"]}, {"X":["a"]}, {"X":1}) == [("a", "X")]
assert solve({"a":["X"],"b":["X"]}, {"X":["b","a"]}, {"X":1}) == [("b", "X")]
assert solve({"a":["X"],"b":["X"]}, {"X":["a","b"]}, {"X":1}) == [("a", "X")]
assert solve({"a":["X"],"b":["X"]}, {"X":["b","a"]}, {"X":2}) == [("a", "X"), ("b", "X")]
assert solve({"a":["X"],"b":["X"]}, {"X":["b","a"]}, {"X":0}) == []
assert solve({"a":["X","Y"],"b":["X"]}, {"X":["b","a"],"Y":["a"]}, {"X":1,"Y":1}) == [("a", "Y"), ("b", "X")]
assert solve({"a":["X","Y"],"b":["X"]}, {"X":["a","b"],"Y":["a"]}, {"X":1,"Y":1}) == [("a", "X")]
assert solve({"a":["X"],"b":["Y"]}, {"X":["a"],"Y":["b"]}, {"X":1,"Y":1}) == [("a", "X"), ("b", "Y")]
assert solve({"a":["Y","X"],"b":["X","Y"]}, {"X":["a","b"],"Y":["b","a"]}, {"X":1,"Y":1}) == [("a", "Y"), ("b", "X")]
assert solve({"a":["Y","X"],"b":["X","Y"]}, {"X":["b","a"],"Y":["a","b"]}, {"X":1,"Y":1}) == [("a", "Y"), ("b", "X")]
assert solve({"a":["X","Y"],"b":["X","Y"],"c":["X","Y"]}, {"X":["c","b","a"],"Y":["a","b","c"]}, {"X":1,"Y":1}) == [("a", "Y"), ("c", "X")]
assert solve({"a":["X","Y"],"b":["X","Y"],"c":["X","Y"]}, {"X":["a","b","c"],"Y":["c","b","a"]}, {"X":2,"Y":1}) == [("a", "X"), ("b", "X"), ("c", "Y")]
assert solve({"a":["X","Y","Z"],"b":["Y","Z","X"],"c":["Z","X","Y"]}, {"X":["a","b","c"],"Y":["b","c","a"],"Z":["c","a","b"]}, {"X":1,"Y":1,"Z":0}) == [("a", "X"), ("b", "Y")]
assert solve({"a":["Y","Z","X"],"b":["Z","X","Y"],"c":["X","Y","Z"]}, {"X":["c","a","b"],"Y":["a","b","c"],"Z":["b","c","a"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Y"), ("b", "Z"), ("c", "X")]
assert solve({"a":["Z","X","Y"],"b":["X","Y","Z"],"c":["Y","Z","X"]}, {"X":["b","c","a"],"Y":["c","a","b"],"Z":["a","b","c"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Z"), ("b", "X"), ("c", "Y")]
assert solve({"a":["X","Y","Z"],"b":["Y","Z","X"],"c":["Z","X","Y"]}, {"X":["a","b","c"],"Y":["b","c","a"],"Z":["c","a","b"]}, {"X":1,"Y":1,"Z":1}) == [("a", "X"), ("b", "Y"), ("c", "Z")]
assert solve({"a":["Y","Z","X"],"b":["Z","X","Y"],"c":["X","Y","Z"]}, {"X":["c","a","b"],"Y":["a","b","c"],"Z":["b","c","a"]}, {"X":1,"Y":1,"Z":0}) == [("a", "Y"), ("c", "X")]
assert solve({"a":["Z","X","Y"],"b":["X","Y","Z"],"c":["Y","Z","X"]}, {"X":["b","c","a"],"Y":["c","a","b"],"Z":["a","b","c"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Z"), ("b", "X"), ("c", "Y")]
assert solve({"a":["X","Y","Z"],"b":["Y","Z","X"],"c":["Z","X","Y"]}, {"X":["a","b","c"],"Y":["b","c","a"],"Z":["c","a","b"]}, {"X":1,"Y":1,"Z":1}) == [("a", "X"), ("b", "Y"), ("c", "Z")]
assert solve({"a":["Y","Z","X"],"b":["Z","X","Y"],"c":["X","Y","Z"]}, {"X":["c","a","b"],"Y":["a","b","c"],"Z":["b","c","a"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Y"), ("b", "Z"), ("c", "X")]
assert solve({"a":["Z","X","Y"],"b":["X","Y","Z"],"c":["Y","Z","X"]}, {"X":["b","c","a"],"Y":["c","a","b"],"Z":["a","b","c"]}, {"X":1,"Y":1,"Z":0}) == [("b", "X"), ("c", "Y")]
assert solve({"a":["X","Y","Z"],"b":["Y","Z","X"],"c":["Z","X","Y"]}, {"X":["a","b","c"],"Y":["b","c","a"],"Z":["c","a","b"]}, {"X":1,"Y":1,"Z":1}) == [("a", "X"), ("b", "Y"), ("c", "Z")]
assert solve({"a":["Y","Z","X"],"b":["Z","X","Y"],"c":["X","Y","Z"]}, {"X":["c","a","b"],"Y":["a","b","c"],"Z":["b","c","a"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Y"), ("b", "Z"), ("c", "X")]
assert solve({"a":["Z","X","Y"],"b":["X","Y","Z"],"c":["Y","Z","X"]}, {"X":["b","c","a"],"Y":["c","a","b"],"Z":["a","b","c"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Z"), ("b", "X"), ("c", "Y")]
assert solve({"a":["X","Y","Z"],"b":["Y","Z","X"],"c":["Z","X","Y"]}, {"X":["a","b","c"],"Y":["b","c","a"],"Z":["c","a","b"]}, {"X":1,"Y":1,"Z":0}) == [("a", "X"), ("b", "Y")]
assert solve({"a":["Y","Z","X"],"b":["Z","X","Y"],"c":["X","Y","Z"]}, {"X":["c","a","b"],"Y":["a","b","c"],"Z":["b","c","a"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Y"), ("b", "Z"), ("c", "X")]
assert solve({"a":["Z","X","Y"],"b":["X","Y","Z"],"c":["Y","Z","X"]}, {"X":["b","c","a"],"Y":["c","a","b"],"Z":["a","b","c"]}, {"X":1,"Y":1,"Z":1}) == [("a", "Z"), ("b", "X"), ("c", "Y")]
